<script setup lang="ts">
import PmsFormDialog from './PmsFormDialog.vue';
import PmsTableControls from './PmsTableControls.vue';
import {ref,onMounted,computed} from 'vue';import {pmsApi} from './api';const props=defineProps<{csrf?:string}>();const emit=defineEmits(['changed']);const editorOpen=ref(false),tablePage=ref(1),tableSize=ref(10),search=ref(''),notice=ref('');const shown=computed(()=>(tab.value==='sent'?sent.value:received.value).filter(row=>[row.recipient,row.recipient_email,row.sender,row.invitable_type,row.project_name,row.invitable_name,row.status,row.delivery_status].join(' ').toLowerCase().includes(search.value.toLowerCase())));const paged=computed(()=>tableSize.value<0?shown.value:shown.value.slice((tablePage.value-1)*tableSize.value,tablePage.value*tableSize.value));const deliveryColors:Record<string,string>={sent:'success',manual:'primary',failed:'danger',quota_reached:'warning',email_disabled:'secondary',not_configured:'secondary',pending:'info'};const data=ref<any>(null),sent=ref<any[]>([]),received=ref<any[]>([]),tab=ref('sent'),busy=ref(false),error=ref(''),result=ref<any>(null),form=ref({name:'',email:'',role_id:'',department_id:'',delivery_method:'manual'});async function load(){const [meta,s,r]=await Promise.all([pmsApi('invitations'),pmsApi('invitations/sent'),pmsApi('invitations/received')]);data.value=meta.data;sent.value=s.data;received.value=r.data;emit('changed',data.value.pending);}async function send(){busy.value=true;error.value='';try{result.value=await pmsApi('invitations/employees',props.csrf,'POST',form.value);editorOpen.value=false;form.value={name:'',email:'',role_id:'',department_id:'',delivery_method:'manual'};await load();if(result.value?.invitation_url&&result.value?.delivery_status==='manual')await copy(result.value.invitation_url);}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}async function respond(token:string,action:string){busy.value=true;error.value='';try{await pmsApi('invitations/'+token+'/respond',props.csrf,'POST',{action});await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}async function copy(value:string){try{await navigator.clipboard.writeText(value);notice.value='Invitation copied.';}catch{error.value='Copy the link manually from the field.';}}onMounted(async()=>{try{await load();}catch(e){error.value=(e as Error).message;}});
</script><template><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p><div class="row g-3 mb-4 pms-invitation-stats"><div v-for="(label,key) in {sent:'Sent',pending:'Pending',accepted:'Accepted'}" :key="key" class="col-md-4"><div class="card h-100"><div class="card-body"><small class="text-muted text-uppercase">{{label}}</small><h3 class="mb-0" :class="key==='pending'?'text-primary':key==='accepted'?'text-success':''">{{data?.[key]||0}}</h3></div></div></div></div><div class="pms-invitation-heading"><div><h4 class="mb-1">Invitations</h4><p class="text-muted mb-0">Track task invitations and employee onboarding from one place.</p></div><button v-if="data?.canInviteEmployees" class="button primary" @click="error='';editorOpen=true"><i aria-hidden="true" class="ti ti-user-plus"></i>Invite employee</button></div><PmsFormDialog v-if="editorOpen" title="Invite employee" subtitle="They will choose their own password from a secure link." @close="editorOpen=false"><form class="pms-invite-form" @submit.prevent="send"><label class="full-width"><span>Email <span class="text-danger">*</span></span><input v-model="form.email" type="email" required placeholder="employee@company.com"></label><label class="full-width">Name (optional)<input v-model="form.name" maxlength="255" placeholder="Employee name"></label><label><span>Role <span class="text-danger">*</span></span><select v-model="form.role_id" required><option value="">Select role</option><option v-for="role in data.roles" :key="role.id" :value="role.id">{{role.role_name}}</option></select></label><label>Department<select v-model="form.department_id"><option value="">No department</option><option v-for="department in data.departments" :key="department.id" :value="department.id">{{department.dept_name}}</option></select></label><div class="alert alert-primary full-width mb-0"><i aria-hidden="true" class="ti ti-shield-check"></i>No temporary password is created. The invitation expires after 7 days.</div><p v-if="error" class="text-danger full-width" role="alert">{{error}}</p><div class="editor-actions full-width"><button type="button" class="button" @click="editorOpen=false">Cancel</button><button class="button" :disabled="busy" @click="form.delivery_method='manual'"><i aria-hidden="true" class="ti ti-copy"></i>{{busy&&form.delivery_method==='manual'?'Creating...':'Create & copy'}}</button><button class="button primary" :disabled="busy" @click="form.delivery_method='email'"><i aria-hidden="true" class="ti ti-send"></i>{{busy&&form.delivery_method==='email'?'Sending...':'Send invitation'}}</button></div></form></PmsFormDialog><div v-if="result" class="notice"><p>{{result.message}}</p><p>{{result.delivery_message}}</p><div class="pms-invitation-result"><input :value="result.invitation_url" readonly aria-label="Created invitation link"><button class="button" @click="copy(result.manual_message||result.invitation_url)"><i aria-hidden="true" class="ti ti-copy"></i>Copy invitation</button></div></div><div v-if="received.length" class="editor-actions mb-3"><button class="button" :class="{primary:tab==='sent'}" @click="tab='sent';tablePage=1">Sent invitations</button><button class="button" :class="{primary:tab==='received'}" @click="tab='received';tablePage=1">Received invitations</button></div><div class="pms-table-card pms-invitation-table"><PmsTableControls :total="shown.length" v-model:page="tablePage" v-model:size="tableSize" v-model:search="search"/><div class="pms-table-scroll"><table class="pms-table"><thead><tr><th>Type</th><th>Context</th><th>Role / Item</th><th>{{tab==='sent'?'To':'From'}}</th><th>Email</th><th>Sent</th><th>Status</th><th>Delivery</th><th>Share</th></tr></thead><tbody><tr v-for="(row,index) in paged" :key="row.id||row.token||index"><td>{{row.invitable_type}}</td><td>{{row.project_name||'-'}}</td><td>{{row.invitable_name}}</td><td>{{row.recipient||row.sender}}</td><td>{{row.recipient_email||'-'}}</td><td>{{row.created_at}}</td><td><span class="badge" :class="'bg-'+(row.status_color||'label-primary')">{{row.status}}</span></td><td><span class="badge text-capitalize" :class="'bg-label-'+(deliveryColors[row.delivery_status]||'secondary')">{{(row.delivery_status||'pending').replaceAll('_',' ')}}</span></td><td><div class="row-actions"><template v-if="row.can_respond"><button class="button primary" :disabled="busy" @click="respond(row.token,'accept')">Accept</button><button class="button" :disabled="busy" @click="respond(row.token,'decline')">Decline</button></template><button v-if="row.invitation_url||row.manual_message" class="button pms-copy-invitation" aria-label="Copy invitation" @click="copy(row.manual_message||row.invitation_url)"><i aria-hidden="true" class="ti ti-copy"></i></button></div></td></tr><tr v-if="!shown.length"><td colspan="9">No invitations yet.</td></tr></tbody></table></div><PmsTableControls footer :total="shown.length" v-model:page="tablePage" v-model:size="tableSize"/></div></template>